import Foundation
import AppKit
import SwiftUI

public struct NothingEarProtocol {
    public static let sppUUIDString = "aeac4a03-dff5-498f-843a-34487cf133eb"
    public static let fastPairUUIDString = "df21fe2c-2515-4fdb-8886-f12c4d67927c"
    
    public static let header: [UInt8] = [0x55, 0x60, 0x01]
    
    public enum Command {
        public static let readBattery: UInt16   = 0xC007
        public static let respBattery: UInt16   = 0x4007
        public static let pushBattery: UInt16   = 0xE001
        
        public static let setANC: UInt16        = 0xF00F
        public static let readANC: UInt16       = 0xC01E
        public static let respANC: UInt16       = 0x401E
        
        public static let setInEar: UInt16      = 0xF00E
        public static let readInEar: UInt16     = 0xC00E
        public static let respInEar: UInt16     = 0x400E
        
        public static let setLowLatency: UInt16 = 0xF040
        public static let readLowLatency: UInt16 = 0xC041
        public static let respLowLatency: UInt16 = 0x4041
        
        public static let setBass: UInt16       = 0xF04E
        public static let readBass: UInt16      = 0xC04E
        public static let respBass: UInt16      = 0x404E
        
        public static let setEQ: UInt16         = 0xF050
        public static let readEQ: UInt16        = 0xC050
        public static let respEQ: UInt16        = 0x4050
        
        public static let ringBuds: UInt16      = 0xF002
    }
    
    public enum ANCMode: UInt8, CaseIterable, Identifiable {
        case off = 0x05
        case transparency = 0x07
        case high = 0x01
        case mid = 0x02
        case low = 0x03
        case adaptive = 0x04
        
        public var id: UInt8 { rawValue }
        
        public var title: String {
            switch self {
            case .high: return "High"
            case .mid: return "Mid"
            case .low: return "Low"
            case .adaptive: return "Adaptive"
            case .off: return "Off"
            case .transparency: return "Transparency"
            }
        }
        
        public var icon: String {
            switch self {
            case .high, .mid, .low, .adaptive: return "speaker.wave.3.fill"
            case .transparency: return "waveform"
            case .off: return "speaker.slash.fill"
            }
        }
    }
    
    public enum EQPreset: UInt8, CaseIterable, Identifiable {
        case balanced = 0x01
        case moreBass = 0x02
        case moreTreble = 0x03
        case voice = 0x04
        
        public var id: UInt8 { rawValue }
        
        public var title: String {
            switch self {
            case .balanced: return "Balanced"
            case .moreBass: return "More Bass"
            case .moreTreble: return "More Treble"
            case .voice: return "Voice"
            }
        }
    }
    
    public struct Frame: Equatable {
        public let command: UInt16
        public let operationID: UInt8
        public let payload: [UInt8]
        
        public init(command: UInt16, operationID: UInt8, payload: [UInt8]) {
            self.command = command
            self.operationID = operationID
            self.payload = payload
        }
    }
    
    /// CRC16-Modbus: poly 0xA001, initial value 0xFFFF
    public static func crc16(_ bytes: [UInt8]) -> UInt16 {
        var crc: UInt16 = 0xFFFF
        for byte in bytes {
            crc ^= UInt16(byte)
            for _ in 0..<8 {
                if (crc & 1) != 0 {
                    crc = (crc >> 1) ^ 0xA001
                } else {
                    crc = crc >> 1
                }
            }
        }
        return crc
    }
    
    /// Encodes a request frame into bytes ready to send over RFCOMM
    public static func encode(command: UInt16, operationID: UInt8 = 1, payload: [UInt8] = []) -> [UInt8] {
        var bytes = header
        bytes.append(UInt8(command & 0xFF))
        bytes.append(UInt8((command >> 8) & 0xFF))
        bytes.append(UInt8(payload.count))
        bytes.append(0x00) // Reserved
        bytes.append(operationID)
        bytes.append(contentsOf: payload)
        
        let checksum = crc16(bytes)
        bytes.append(UInt8(checksum & 0xFF))
        bytes.append(UInt8((checksum >> 8) & 0xFF))
        return bytes
    }
    
    public static func createReadBatteryFrame(operationID: UInt8 = 1) -> [UInt8] {
        return encode(command: Command.readBattery, operationID: operationID)
    }
    
    public static func createSetANCFrame(mode: ANCMode, operationID: UInt8 = 1) -> [UInt8] {
        return encode(command: Command.setANC, operationID: operationID, payload: [0x01, mode.rawValue, 0x00])
    }
    
    public static func createReadANCFrame(operationID: UInt8 = 1) -> [UInt8] {
        return encode(command: Command.readANC, operationID: operationID, payload: [])
    }
    
    public static func createSetInEarFrame(enable: Bool, operationID: UInt8 = 1) -> [UInt8] {
        return encode(command: Command.setInEar, operationID: operationID, payload: [0x02, 0x01, enable ? 0x01 : 0x00])
    }
    
    public static func createSetLowLatencyFrame(enable: Bool, operationID: UInt8 = 1) -> [UInt8] {
        return encode(command: Command.setLowLatency, operationID: operationID, payload: [enable ? 0x01 : 0x02])
    }
    
    public static func createSetEnhancedBassFrame(enable: Bool, level: Int = 3, operationID: UInt8 = 1) -> [UInt8] {
        let rawLevel = enable ? UInt8(max(1, min(5, level)) * 2) : 0
        return encode(command: Command.setBass, operationID: operationID, payload: [enable ? 0x01 : 0x00, rawLevel])
    }
    
    public static func createSetEQFrame(preset: EQPreset, operationID: UInt8 = 1) -> [UInt8] {
        return encode(command: Command.setEQ, operationID: operationID, payload: [preset.rawValue])
    }
    
    public static func createRingBudsFrame(earbud: UInt8, start: Bool, operationID: UInt8 = 1) -> [UInt8] {
        return encode(command: Command.ringBuds, operationID: operationID, payload: [earbud, start ? 0x01 : 0x00])
    }
    
    /// Extracts complete frames from the incoming RFCOMM byte stream buffer
    public static func extractFrames(from buffer: inout [UInt8]) -> [Frame] {
        var frames = [Frame]()
        
        while buffer.count >= 8 {
            // Find header prefix 0x55, 0x60, 0x01
            guard buffer[0] == header[0], buffer[1] == header[1], buffer[2] == header[2] else {
                buffer.removeFirst()
                continue
            }
            
            let payloadLen = Int(buffer[5])
            let totalLength = 8 + payloadLen + 2 // header(8) + payload + crc(2)
            
            guard buffer.count >= totalLength else {
                // Wait for more data to arrive
                break
            }
            
            let frameBytes = Array(buffer.prefix(totalLength))
            buffer.removeFirst(totalLength)
            
            let bodyBytes = Array(frameBytes.prefix(8 + payloadLen))
            let expectedCRC = crc16(bodyBytes)
            let receivedCRC = UInt16(frameBytes[8 + payloadLen]) | (UInt16(frameBytes[9 + payloadLen]) << 8)
            
            if expectedCRC == receivedCRC {
                let cmd = UInt16(frameBytes[3]) | (UInt16(frameBytes[4]) << 8)
                let opID = frameBytes[7]
                let payload = Array(frameBytes[8..<(8 + payloadLen)])
                frames.append(Frame(command: cmd, operationID: opID, payload: payload))
            } else {
                print("[NothingEarProtocol] Checksum mismatch: expected 0x\(String(expectedCRC, radix: 16)), received 0x\(String(receivedCRC, radix: 16))")
            }
        }
        
        return frames
    }
    
    /// Parses battery payload received from Nothing Ear
    /// Format: payload[0] = connected devices count
    /// For each device: deviceId (UInt8), rawValue (UInt8)
    /// deviceId: 0x02 = Left, 0x03 = Right, 0x04 = Case
    /// rawValue: lower 7 bits = percentage (0-100), MSB 0x80 = isCharging
    public static func parseBatteryPayload(_ payload: [UInt8]) -> BatteryState? {
        guard !payload.isEmpty else { return nil }
        
        let count = Int(payload[0])
        guard payload.count >= 1 + (count * 2) else { return nil }
        
        var state = BatteryState()
        
        for i in 0..<count {
            let deviceId = payload[1 + (i * 2)]
            let raw = payload[2 + (i * 2)]
            let level = Int(raw & 0x7F)
            let isCharging = (raw & 0x80) != 0
            
            switch deviceId {
            case 0x02: // Left Bud
                state.leftPercentage = level
                state.isLeftCharging = isCharging
            case 0x03: // Right Bud
                state.rightPercentage = level
                state.isRightCharging = isCharging
            case 0x04: // Case
                state.casePercentage = level
                state.isCaseCharging = isCharging
            default:
                break
            }
        }
        
        return state
    }
}


// MARK: - Authentic Nothing Ear Real Image Assets

public enum NothingEarAssets {
    private static let leftBudBase64 = ""
    public static let leftBud: NSImage = {
        guard let data = Data(base64Encoded: leftBudBase64), let img = NSImage(data: data) else { return NSImage() }
        img.size = NSSize(width: 64, height: 64)
        return img
    }()
    private static let rightBudBase64 = ""
    public static let rightBud: NSImage = {
        guard let data = Data(base64Encoded: rightBudBase64), let img = NSImage(data: data) else { return NSImage() }
        img.size = NSSize(width: 64, height: 64)
        return img
    }()
    private static let caseBoxBase64 = ""
    public static let caseBox: NSImage = {
        guard let data = Data(base64Encoded: caseBoxBase64), let img = NSImage(data: data) else { return NSImage() }
        img.size = NSSize(width: 64, height: 64)
        return img
    }()
    private static let duoBudsBase64 = ""
    public static let duoBuds: NSImage = {
        guard let data = Data(base64Encoded: duoBudsBase64), let img = NSImage(data: data) else { return NSImage() }
        img.size = NSSize(width: 64, height: 64)
        return img
    }()

    public static func menuBarImage(dotColor: NSColor?) -> NSImage {
        let targetSize = NSSize(width: 24, height: 20)
        let finalImg = NSImage(size: targetSize)
        finalImg.lockFocus()
        
        let iconRect = NSRect(x: 1, y: 1, width: 22, height: 18)
        duoBuds.draw(in: iconRect, from: NSRect(origin: .zero, size: duoBuds.size), operation: .sourceOver, fraction: 1.0)
        
        if let dotColor = dotColor {
            let dotRect = NSRect(x: 17.5, y: 12.5, width: 5.5, height: 5.5)
            let shadow = NSShadow()
            shadow.shadowColor = NSColor.black.withAlphaComponent(0.4)
            shadow.shadowOffset = NSSize(width: 0, height: -0.5)
            shadow.shadowBlurRadius = 1
            shadow.set()
            
            let path = NSBezierPath(ovalIn: dotRect)
            dotColor.setFill()
            path.fill()
        }
        
        finalImg.unlockFocus()
        return finalImg
    }
}

public struct NothingEarIcons {
    public static func earbudImage(isLeft: Bool, size: CGSize = CGSize(width: 24, height: 24)) -> NSImage {
        return isLeft ? NothingEarAssets.leftBud : NothingEarAssets.rightBud
    }
    
    public static func caseImage(size: CGSize = CGSize(width: 24, height: 24)) -> NSImage {
        return NothingEarAssets.caseBox
    }
}

public struct NothingEarbudIconView: View {
    public let isLeft: Bool
    public var size: CGFloat = 26
    public var opacity: Double = 1.0
    
    public init(isLeft: Bool, size: CGFloat = 26, opacity: Double = 1.0) {
        self.isLeft = isLeft
        self.size = size
        self.opacity = opacity
    }
    
    public var body: some View {
        Image(nsImage: isLeft ? NothingEarAssets.leftBud : NothingEarAssets.rightBud)
            .resizable()
            .aspectRatio(contentMode: .fit)
            .frame(width: size, height: size)
            .opacity(opacity)
    }
}

public struct NothingCaseIconView: View {
    public var size: CGFloat = 26
    public var opacity: Double = 1.0
    
    public init(size: CGFloat = 26, opacity: Double = 1.0) {
        self.size = size
        self.opacity = opacity
    }
    
    public var body: some View {
        Image(nsImage: NothingEarAssets.caseBox)
            .resizable()
            .aspectRatio(contentMode: .fit)
            .frame(width: size, height: size)
            .opacity(opacity)
    }
}
